#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 int minimumScore(string s,string t){
  int n=s.size(),m=t.size();vector<int> left(m+1,n),right(m+1,-1);
  left[0]=-1;int p=0;
  for(int i=0;i<n&&p<m;++i)if(s[i]==t[p])left[++p]=i;
  right[m]=n;p=m-1;
  for(int i=n-1;i>=0&&p>=0;--i)if(s[i]==t[p])right[p--]=i;
  int ans=m;
  for(int i=0;i<=m;++i){if(i>0&&left[i]==n)break;
   int lo=i,hi=m;
   while(lo<hi){int mid=lo+(hi-lo)/2;if(right[mid]>left[i])hi=mid;else lo=mid+1;}
   if(right[lo]>left[i])ans=min(ans,lo-i);
  }
  return ans;
 }
};
